cypress_script:
describe('Checkbox Form', () => {
  it('should toggle checkboxes successfully', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.get('input[type="checkbox"]').last().check();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/checkboxes');
  });
  it('should not change URL when checkboxes are toggled', () => {
    cy.visit('https://the-internet.herokuapp.com/checkboxes');
    cy.get('input[type="checkbox"]').first().check();
    cy.get('input[type="checkbox"]').last().uncheck();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/checkboxes');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkbox Form', () => {
  test('should toggle checkboxes successfully', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await page.locator('input[type="checkbox"]').first().check();
    await page.locator('input[type="checkbox"]').last().check();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
  });
  test('should not change URL when checkboxes are toggled', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/checkboxes');
    await page.locator('input[type="checkbox"]').first().check();
    await page.locator('input[type="checkbox"]').last().uncheck();
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/checkboxes');
  });
});
